import { type JSX, createContext, useContext } from "solid-js";
import type { ReducedMotion, Transition, VariantLabels } from "#/lib/motion/types";

export interface MotionConfigValue {
  readonly transition: Transition | undefined;
  readonly reducedMotion: ReducedMotion | undefined;
}

export const MotionConfigContext = createContext<MotionConfigValue>();

export function MotionConfig(props: {
  transition?: Transition;
  reducedMotion?: ReducedMotion;
  children?: JSX.Element;
}) {
  const parent = useContext(MotionConfigContext);
  const value: MotionConfigValue = {
    get transition() {
      return props.transition ?? parent?.transition;
    },
    get reducedMotion() {
      return props.reducedMotion ?? parent?.reducedMotion;
    },
  };
  return (
    <MotionConfigContext.Provider value={value}>{props.children}</MotionConfigContext.Provider>
  );
}

export interface VariantContextValue {
  readonly initial: VariantLabels | false | undefined;
  readonly animate: VariantLabels | undefined;
}

export const VariantContext = createContext<VariantContextValue>();

import {
  attachSpring,
  cancelFrame,
  frame,
  inView,
  isMotionValue,
  motionValue,
  scrollInfo,
  transformValue,
  animate as animateTarget,
  type MotionValue,
  type SpringOptions,
} from "motion";
import { type Accessor, createEffect, createSignal, onCleanup, untrack } from "solid-js";
import { startDragControls } from "./state";
import type {
  AnimationControls,
  AnimationRunner,
  DragControls,
  Target,
  TargetResolver,
  Transition,
} from "./types";

type FrameData = { timestamp: number; delta: number };
type ScrollOptions = {
  container?: Element;
  target?: Element;
  offset?: Parameters<typeof scrollInfo>[1] extends infer Options
    ? Options extends { offset?: infer Offset }
      ? Offset
      : never
    : never;
};

function read<T>(source: T | Accessor<T>): T {
  return typeof source === "function" ? (source as Accessor<T>)() : source;
}

export function useMotionValue<T>(initial: T): MotionValue<T> {
  const value = motionValue(initial);
  onCleanup(() => value.destroy());
  return value;
}

export function useSpring<T extends number | string>(
  source: T | MotionValue<T> | Accessor<T | MotionValue<T>>,
  options?: SpringOptions | Accessor<SpringOptions | undefined>,
): MotionValue<T> {
  const initial = untrack(() => read(source));
  const value = motionValue(isMotionValue(initial) ? initial.get() : initial);
  createEffect(() => {
    const stop = attachSpring(value, read(source), read(options ?? {}));
    onCleanup(stop);
  });
  onCleanup(() => value.destroy());
  return value;
}

export function useTransform<I, O>(
  value: MotionValue<I>,
  transformer: (input: I) => O,
): MotionValue<O> {
  const derived = transformValue(() => transformer(value.get()));
  onCleanup(() => derived.destroy());
  return derived;
}

export function useMotionTemplate(
  strings: TemplateStringsArray,
  ...values: Array<MotionValue | string | number>
): MotionValue<string> {
  const value = transformValue(() => {
    let rendered = strings[0] ?? "";
    for (let index = 0; index < values.length; index++) {
      const piece = values[index];
      const text = isMotionValue(piece) ? String(piece.get()) : String(piece ?? "");
      rendered += text + (strings[index + 1] ?? "");
    }
    return rendered;
  });
  onCleanup(() => value.destroy());
  return value;
}

export function useVelocity(value: MotionValue<number>): MotionValue<number> {
  const velocity = motionValue(value.getVelocity());
  createEffect(() => {
    const stop = value.on("change", () => {
      velocity.set(value.getVelocity());
    });
    onCleanup(stop);
  });
  onCleanup(() => velocity.destroy());
  return velocity;
}

export function useTime(): MotionValue<number> {
  const time = motionValue(0);
  const step = ({ timestamp }: FrameData) => {
    time.set(timestamp);
  };
  frame.update(step, true);
  onCleanup(() => {
    cancelFrame(step);
    time.destroy();
  });
  return time;
}

export function useAnimationFrame(callback: (timestamp: number, delta: number) => void) {
  createEffect(() => {
    const step = ({ timestamp, delta }: FrameData) => {
      callback(timestamp, delta);
    };
    frame.update(step, true);
    onCleanup(() => cancelFrame(step));
  });
}

export function useMotionValueEvent<T>(
  value: MotionValue<T>,
  event: "change",
  callback: (latest: T) => void,
) {
  createEffect(() => {
    const stop = value.on(event, callback);
    onCleanup(stop);
  });
}

type ViewOptions = {
  root?: Element | Document;
  margin?: `${number}${"px" | "%"}`;
  amount?: "some" | "all" | number;
  once?: boolean;
};

export function useInView(
  target: Accessor<Element | undefined>,
  options?: ViewOptions | Accessor<ViewOptions | undefined>,
): Accessor<boolean> {
  const [visible, setVisible] = createSignal(false);
  createEffect(() => {
    const element = target();
    if (!element) return;
    const opts = options === undefined ? undefined : read(options);
    const stop = inView(
      element,
      () => {
        setVisible(true);
        if (opts?.once) return;
        return () => setVisible(false);
      },
      opts,
    );
    onCleanup(() => {
      stop();
      setVisible(false);
    });
  });
  return visible;
}

export function useReducedMotion(): Accessor<boolean> {
  const [reduced, setReduced] = createSignal(false);
  createEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    onCleanup(() => query.removeEventListener("change", update));
  });
  return reduced;
}

export function useScroll(options?: ScrollOptions | Accessor<ScrollOptions | undefined>) {
  const scrollX = motionValue(0);
  const scrollY = motionValue(0);
  const scrollXProgress = motionValue(0);
  const scrollYProgress = motionValue(0);
  createEffect(() => {
    const opts = options === undefined ? {} : (read(options) ?? {});
    const stop = scrollInfo(
      (info) => {
        scrollX.set(info.x.current);
        scrollY.set(info.y.current);
        scrollXProgress.set(info.x.progress);
        scrollYProgress.set(info.y.progress);
      },
      {
        container: opts.container,
        target: opts.target,
        offset: opts.offset,
      },
    );
    onCleanup(stop);
  });
  onCleanup(() => {
    scrollX.destroy();
    scrollY.destroy();
    scrollXProgress.destroy();
    scrollYProgress.destroy();
  });
  return { scrollX, scrollY, scrollXProgress, scrollYProgress };
}

export function useAnimate() {
  let scope: Element | undefined;
  const ref = (element: Element | null) => {
    scope = element ?? undefined;
  };
  function isTarget(value: Target | Transition | undefined): value is Target {
    return (
      !!value &&
      typeof value === "object" &&
      !("duration" in value) &&
      !("type" in value) &&
      !("stiffness" in value)
    );
  }

  function animateScope(target: Target, options?: Transition): ReturnType<typeof animateTarget>;
  function animateScope(
    selector: string,
    target: Target,
    options?: Transition,
  ): ReturnType<typeof animateTarget>;
  function animateScope(
    element: Element,
    target: Target,
    options?: Transition,
  ): ReturnType<typeof animateTarget>;
  function animateScope(
    targetOrSelector: Target | string | Element,
    targetOrOptions?: Target | Transition,
    options?: Transition,
  ) {
    if (typeof targetOrSelector === "string" || targetOrSelector instanceof Element) {
      const subject =
        typeof targetOrSelector === "string"
          ? (scope?.querySelector(targetOrSelector) ?? targetOrSelector)
          : targetOrSelector;
      if (!isTarget(targetOrOptions)) return;
      return animateTarget(subject, targetOrOptions, options);
    }
    const node = scope;
    if (!node) return;
    const transition = isTarget(targetOrOptions) ? undefined : targetOrOptions;
    return animateTarget(node, targetOrSelector, transition);
  }
  return [ref, animateScope] as const;
}

export function useAnimation(): AnimationControls {
  const runners = new Set<AnimationRunner>();
  const controls: AnimationControls = {
    start(definition: TargetResolver, transition?: Transition) {
      return Promise.all([...runners].map((runner) => runner.start(definition, transition))).then(
        () => undefined,
      );
    },
    set(definition: TargetResolver) {
      for (const runner of runners) runner.set(definition);
    },
    stop() {
      for (const runner of runners) runner.stop();
    },
    subscribe(runner: AnimationRunner) {
      runners.add(runner);
      return () => runners.delete(runner);
    },
  };
  onCleanup(() => {
    runners.clear();
  });
  return controls;
}

export function useDragControls(): DragControls {
  const controls: DragControls = {
    start(event: PointerEvent) {
      startDragControls(controls, event);
    },
  };
  return controls;
}

import { isMotionValue } from "motion";
import {
  type Component,
  createEffect,
  on,
  onCleanup,
  splitProps,
  untrack,
  useContext,
} from "solid-js";
import { Dynamic } from "solid-js/web";
import { MotionConfigContext, VariantContext, type VariantContextValue } from "./context";
import { PresenceContext } from "./presence";
import {
  instantTarget,
  isLabel,
  omitKeys,
  resolveVariant,
  stripTarget,
  styleMotionValues,
} from "#/lib/utils/motion/resolve";
import { scheduleMotion } from "#/lib/motion/schedule";
import { MotionState, type MotionSnapshot } from "#/lib/motion/state";
import { isTransformKey, pinPopLayout, targetToStyle } from "#/lib/utils/motion/target-style";
import {
  motionPropKeys,
  type AnimationControls,
  type MotionComponentProps,
  type MotionStyle,
} from "#/lib/motion/types";

const components = new Map<string, Component<MotionComponentProps>>();

function isControls(value: unknown): value is AnimationControls {
  if (!value || typeof value !== "object") return false;
  return "subscribe" in value && "start" in value && "stop" in value;
}

function staticStyle(style: MotionStyle | undefined): Record<string, string | number> {
  const css: Record<string, string | number> = {};
  if (!style) return css;
  for (const [key, value] of Object.entries(style)) {
    if (typeof value === "number" || typeof value === "string") css[key] = value;
  }
  return css;
}

function createMotionComponent(tag: string): Component<MotionComponentProps> {
  return (props) => {
    const [local, rest] = splitProps(props, motionPropKeys);
    const config = useContext(MotionConfigContext);
    const presence = useContext(PresenceContext);
    const parent = useContext(VariantContext);
    const state = new MotionState();
    let element: Element | undefined;
    let leaving = false;
    let pinned: (() => void) | undefined;

    const variants: VariantContextValue = {
      get initial() {
        if (isLabel(local.initial) || local.initial === false) return local.initial;
        return parent?.initial;
      },
      get animate() {
        if (isLabel(local.animate)) return local.animate;
        return parent?.animate;
      },
    };

    const initialStyle = untrack(() => {
      const block = presence?.blockInitial() ?? false;
      const jump = block || local.initial === false;
      const definition = jump
        ? isControls(local.animate)
          ? parent?.animate
          : (local.animate ?? parent?.animate)
        : local.initial !== undefined
          ? local.initial
          : local.inherit === false
            ? undefined
            : parent?.initial;
      const resolved =
        definition === undefined || definition === false || isControls(definition)
          ? undefined
          : resolveVariant(definition, local.variants, local.custom);
      const pose = omitKeys(
        instantTarget(stripTarget(resolved)),
        Object.keys(styleMotionValues(local.style)),
      );
      return { ...targetToStyle(pose), ...staticStyle(local.style) };
    });

    function capture(): MotionSnapshot {
      return {
        initial: local.initial,
        animate: local.animate,
        exit: local.exit,
        variants: local.variants,
        transition: local.transition ?? config?.transition,
        custom: presence?.hasCustom ? presence.custom() : local.custom,
        inherit: local.inherit !== false,
        parentInitial: parent?.initial,
        parentAnimate: parent?.animate,
        blockInitial: presence?.blockInitial() ?? false,
        reducedMotion: config?.reducedMotion,
        whileHover: local.whileHover,
        whileTap: local.whileTap,
        whileFocus: local.whileFocus,
        whileInView: local.whileInView,
        whileDrag: local.whileDrag,
        drag: local.drag,
        dragConstraints: local.dragConstraints,
        dragElastic: local.dragElastic,
        dragMomentum: local.dragMomentum,
        dragSnapToOrigin: local.dragSnapToOrigin,
        dragDirectionLock: local.dragDirectionLock,
        dragPropagation: local.dragPropagation,
        dragControls: local.dragControls,
        viewport: local.viewport,
        onHoverStart: local.onHoverStart,
        onHoverEnd: local.onHoverEnd,
        onTap: local.onTap,
        onTapStart: local.onTapStart,
        onTapCancel: local.onTapCancel,
        onDragStart: local.onDragStart,
        onDrag: local.onDrag,
        onDragEnd: local.onDragEnd,
        onViewportEnter: local.onViewportEnter,
        onViewportLeave: local.onViewportLeave,
        onUpdate: local.onUpdate,
        styleValues: styleMotionValues(local.style),
      };
    }

    function setRef(node: Element) {
      element = node;
      state.attach(node);
      const ref = local.ref;
      if (typeof ref === "function") ref(node);
    }

    createEffect(() => {
      const present = presence?.isPresent() ?? true;
      const snap = capture();
      if (!present) {
        if (leaving) return;
        leaving = true;
        state.prepare(snap);
        const node = element;
        pinned =
          presence?.popLayout() && node instanceof HTMLElement
            ? pinPopLayout(node, presence.anchorX(), presence.anchorY())
            : undefined;
        const done = state.exit().finally(() => {
          if (leaving) return;
          pinned?.();
          pinned = undefined;
        });
        presence?.registerExit(done);
        return;
      }
      if (leaving) {
        leaving = false;
        pinned?.();
        pinned = undefined;
        state.cancelExit();
      }
      scheduleMotion(() => state.apply(snap));
    });

    // `initialStyle` covers the first paint. Later changes to plain (non-MotionValue) style
    // values are written here; transform keys stay with MotionState.
    createEffect(
      on(
        () => staticStyle(local.style),
        (next, prev) => {
          const node = element;
          if (!prev || !(node instanceof HTMLElement || node instanceof SVGElement)) return;
          for (const key of Object.keys(prev)) {
            if (!(key in next) && !isTransformKey(key)) node.style.removeProperty(key);
          }
          for (const [key, value] of Object.entries(next)) {
            if (isTransformKey(key) || prev[key] === value) continue;
            node.style.setProperty(key, String(value));
          }
        },
        { defer: true },
      ),
    );

    createEffect(() => {
      const child = local.children;
      const node = element;
      if (!node || !isMotionValue(child)) return;
      node.textContent = String(child.get());
      const stop = child.on("change", (latest) => {
        node.textContent = String(latest);
      });
      onCleanup(stop);
    });

    onCleanup(() => state.destroy());

    const rendered = () => {
      const child = local.children;
      if (isMotionValue(child)) return String(untrack(() => child.get()));
      return child;
    };

    return (
      <VariantContext.Provider value={variants}>
        <Dynamic component={tag} {...rest} ref={setRef} style={initialStyle}>
          {rendered()}
        </Dynamic>
      </VariantContext.Provider>
    );
  };
}

type MotionProxy = {
  [tag: string]: Component<MotionComponentProps>;
};

export const motion: MotionProxy = new Proxy({} as MotionProxy, {
  get(_target, key) {
    if (typeof key !== "string") return undefined;
    const cached = components.get(key);
    if (cached) return cached;
    const created = createMotionComponent(key);
    components.set(key, created);
    return created;
  },
});

import {
  type Accessor,
  type JSX,
  Show,
  createContext,
  createEffect,
  createMemo,
  createRoot,
  createSignal,
  onCleanup,
  onMount,
  untrack,
  useContext,
} from "solid-js";
import { For } from "solid-js";

export interface PresenceState {
  isPresent: () => boolean;
  blockInitial: () => boolean;
  popLayout: () => boolean;
  anchorX: () => "left" | "right";
  anchorY: () => "top" | "bottom";
  hasCustom: boolean;
  custom: () => unknown;
  registerExit: (done: Promise<void>) => void;
}

export const PresenceContext = createContext<PresenceState>();

export function useIsPresent(): Accessor<boolean> {
  const presence = useContext(PresenceContext);
  return () => presence?.isPresent() ?? true;
}

export type PresenceMode = "sync" | "wait" | "popLayout";

export interface AnimatePresenceProps<T = unknown> {
  when?: boolean | Accessor<boolean>;
  each?: readonly T[] | Accessor<readonly T[]>;
  by?: (item: T) => string | number;
  mode?: PresenceMode;
  initial?: boolean;
  custom?: unknown;
  anchorX?: "left" | "right";
  anchorY?: "top" | "bottom";
  onExitComplete?: () => void;
  children?: JSX.Element | ((item: T, index: Accessor<number>) => JSX.Element);
}

interface Row<T> {
  key: string;
  item: T;
  index: number;
  present: Accessor<boolean>;
  setPresent: (present: boolean) => void;
}

function readFlag(source: boolean | Accessor<boolean> | undefined, fallback: boolean): boolean {
  if (source === undefined) return fallback;
  if (typeof source === "function") return source();
  return source;
}

function readList<T>(
  source: readonly T[] | Accessor<readonly T[]> | undefined,
): readonly T[] | undefined {
  if (source === undefined) return undefined;
  if (typeof source === "function") {
    const value = source();
    return Array.isArray(value) ? value : undefined;
  }
  return source;
}

export function AnimatePresence<T>(props: AnimatePresenceProps<T>) {
  const block = { current: props.initial === false };
  onMount(() => {
    queueMicrotask(() => {
      block.current = false;
    });
  });

  const objectIds = new WeakMap<object, number>();
  let nextId = 1;

  function keyFor(item: T, _index: number): string {
    if (props.by) return String(props.by(item));
    if (typeof item === "object" && item !== null) {
      const found = objectIds.get(item);
      if (found !== undefined) return `o${found}`;
      const id = nextId;
      nextId += 1;
      objectIds.set(item, id);
      return `o${id}`;
    }
    return `p${String(item)}`;
  }

  const roots = new Map<string, { dispose: () => void; row: Row<T> }>();
  const entered = new Set<string>();

  function ensure(item: T, index: number): Row<T> {
    const key = keyFor(item, index);
    const found = roots.get(key);
    if (found) {
      found.row.item = item;
      found.row.index = index;
      found.row.setPresent(true);
      return found.row;
    }
    let row: Row<T> | undefined;
    const dispose = createRoot((done) => {
      const [present, setPresent] = createSignal(true);
      row = { key, item, index, present, setPresent };
      return done;
    });
    if (!row) throw new Error("AnimatePresence failed to create a row");
    roots.set(key, { dispose, row });
    return row;
  }

  const [order, setOrder] = createSignal<Row<T>[]>(
    untrack(() => {
      const list = readList(props.each);
      if (!list) return [];
      return list.map((item, index) => ensure(item, index));
    }),
  );

  function finish(key: string) {
    entered.delete(key);
    setOrder((rows) => rows.filter((row) => row.key !== key));
    queueMicrotask(() => {
      const found = roots.get(key);
      roots.delete(key);
      found?.dispose();
    });
    const stillExiting = untrack(order).some((row) => !row.present());
    if (!stillExiting) props.onExitComplete?.();
  }

  createEffect(() => {
    const list = readList(props.each);
    if (!list) return;
    const prev = untrack(order);
    const presentRows = list.map((item, index) => ensure(item, index));
    const presentKeys = new Set(presentRows.map((row) => row.key));
    const merged = presentRows.slice();
    prev.forEach((row, index) => {
      if (presentKeys.has(row.key)) return;
      row.setPresent(false);
      merged.splice(Math.min(index, merged.length), 0, row);
    });
    setOrder(merged);
  });

  const shown = createMemo(() => {
    const rows = order();
    const waiting = props.mode === "wait" && rows.some((row) => !row.present());
    const visible: Row<T>[] = [];
    for (const row of rows) {
      if (!row.present()) {
        visible.push(row);
        continue;
      }
      if (waiting && !entered.has(row.key)) continue;
      entered.add(row.key);
      visible.push(row);
    }
    return visible;
  });

  const listMode = createMemo(() => readList(props.each) !== undefined);

  return (
    <Show
      when={listMode()}
      fallback={
        <WhenPresence
          when={props.when}
          mode={props.mode}
          custom={props.custom}
          anchorX={props.anchorX}
          anchorY={props.anchorY}
          block={block}
          onExitComplete={props.onExitComplete}
        >
          {props.children as JSX.Element}
        </WhenPresence>
      }
    >
      <For each={shown()}>
        {(row) => (
          <PresenceScope
            present={row.present}
            mode={props.mode}
            custom={props.custom}
            anchorX={props.anchorX}
            anchorY={props.anchorY}
            block={block}
            onDone={() => finish(row.key)}
          >
            {typeof props.children === "function"
              ? props.children(row.item, () => row.index)
              : props.children}
          </PresenceScope>
        )}
      </For>
    </Show>
  );
}

function WhenPresence(props: {
  when?: boolean | Accessor<boolean>;
  mode?: PresenceMode;
  custom?: unknown;
  anchorX?: "left" | "right";
  anchorY?: "top" | "bottom";
  block: { current: boolean };
  onExitComplete?: () => void;
  children?: JSX.Element;
}) {
  const [mounted, setMounted] = createSignal(untrack(() => readFlag(props.when, true)));
  const [present, setPresent] = createSignal(true);
  let pendingShow = false;

  createEffect(() => {
    const show = readFlag(props.when, true);
    if (show) {
      if (props.mode === "wait" && untrack(mounted) && !untrack(present)) {
        pendingShow = true;
        return;
      }
      pendingShow = false;
      setMounted(true);
      setPresent(true);
      return;
    }
    if (!untrack(mounted)) return;
    setPresent(false);
  });

  function done() {
    if (readFlag(props.when, true) && props.mode !== "wait") return;
    setMounted(false);
    if (pendingShow || (props.mode === "wait" && readFlag(props.when, true))) {
      pendingShow = false;
      setPresent(true);
      setMounted(true);
      return;
    }
    props.onExitComplete?.();
  }

  return (
    <Show when={mounted()}>
      <PresenceScope
        present={present}
        mode={props.mode}
        custom={props.custom}
        anchorX={props.anchorX}
        anchorY={props.anchorY}
        block={props.block}
        onDone={done}
      >
        {props.children}
      </PresenceScope>
    </Show>
  );
}

function PresenceScope(props: {
  present: Accessor<boolean>;
  mode?: PresenceMode;
  custom?: unknown;
  anchorX?: "left" | "right";
  anchorY?: "top" | "bottom";
  block: { current: boolean };
  onDone: () => void;
  children?: JSX.Element;
}) {
  const exits: Promise<void>[] = [];
  let token = 0;
  const api: PresenceState = {
    isPresent: () => props.present(),
    blockInitial: () => props.block.current,
    popLayout: () => props.mode === "popLayout",
    anchorX: () => props.anchorX ?? "left",
    anchorY: () => props.anchorY ?? "top",
    hasCustom: props.custom !== undefined,
    custom: () => props.custom,
    registerExit(done) {
      exits.push(done);
    },
  };

  createEffect(() => {
    if (props.present()) {
      token += 1;
      exits.length = 0;
      return;
    }
    const current = token + 1;
    token = current;
    queueMicrotask(() => {
      if (current !== token) return;
      const pending = exits.slice();
      if (pending.length === 0) {
        props.onDone();
        return;
      }
      void Promise.all(pending).then(() => {
        if (current === token) props.onDone();
      });
    });
  });

  onCleanup(() => {
    token += 1;
  });

  return <PresenceContext.Provider value={api}>{props.children}</PresenceContext.Provider>;
}

import { isMotionValue } from "motion";
import type { MotionValue } from "motion";
import type { MotionStyle } from "#/lib/motion/types";
import type {
  Animatable,
  Target,
  TargetAndTransition,
  TargetResolver,
  Transition,
  VariantLabels,
  Variants,
} from "#/lib/motion/types";

export function isLabel(value: unknown): value is VariantLabels {
  if (typeof value === "string") return true;
  return Array.isArray(value) && value.every((item) => typeof item === "string");
}

export function isAnimatable(value: unknown): value is Animatable {
  if (typeof value === "number" || typeof value === "string") return true;
  if (isMotionValue(value)) return false;
  return (
    Array.isArray(value) &&
    value.every((item) => typeof item === "number" || typeof item === "string")
  );
}

export function labelsOf(value: VariantLabels): string[] {
  return typeof value === "string" ? [value] : value;
}

export function resolveVariant(
  definition: TargetResolver | undefined,
  variants: Variants | undefined,
  custom: unknown,
): TargetAndTransition | undefined {
  if (definition == null || definition === false || typeof definition === "boolean")
    return undefined;
  if (isLabel(definition)) {
    const label = typeof definition === "string" ? definition : definition[definition.length - 1];
    return resolveVariant(variants?.[label], variants, custom);
  }
  if (typeof definition === "function") return definition(custom);
  return definition;
}

export function stripTarget(definition: TargetAndTransition | undefined): Target {
  const target: Target = {};
  if (!definition) return target;
  for (const key in definition) {
    if (key === "transition") continue;
    const value = definition[key];
    if (isAnimatable(value)) target[key] = value;
  }
  return target;
}

/** First keyframe, for the pre-animation pose. */
export function instantTarget(target: Target): Target {
  const next: Target = {};
  for (const key in target) {
    const value = target[key];
    if (Array.isArray(value)) {
      const first = value[0];
      if (first !== undefined) next[key] = first;
    } else if (value !== undefined) {
      next[key] = value;
    }
  }
  return next;
}

export function omitKeys(target: Target, keys: Iterable<string>): Target {
  const next: Target = { ...target };
  for (const key of keys) delete next[key];
  return next;
}

export function transitionFor(
  base: Transition | undefined,
  variant: TargetAndTransition | undefined,
  onUpdate: ((latest: unknown) => void) | undefined,
  reduced: boolean,
): Transition {
  const merged: Transition = { ...base, ...variant?.transition };
  if (onUpdate) merged.onUpdate = onUpdate;
  if (reduced) merged.duration = 0;
  return merged;
}

export function styleMotionValues(style: MotionStyle | undefined): Record<string, MotionValue> {
  const values: Record<string, MotionValue> = {};
  if (!style) return values;
  for (const [key, value] of Object.entries(style)) {
    if (isMotionValue(value)) values[key] = value;
  }
  return values;
}

export function sameMotionValues(
  left: Record<string, MotionValue> | undefined,
  right: Record<string, MotionValue>,
): boolean {
  const a = left ?? {};
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(right);
  if (aKeys.length !== bKeys.length) return false;
  return bKeys.every((key) => a[key] === right[key]);
}

export function prefersReducedMotion(): boolean {
  return (
    typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

const queue: Array<() => void> = [];
let scheduled = false;

/**
 * Run one commit's animations after every node has its new props.
 * Children register after parents, and the batch runs in reverse so
 * children animate first.
 */
export function scheduleMotion(run: () => void) {
  queue.push(run);
  if (scheduled) return;
  scheduled = true;
  queueMicrotask(() => {
    scheduled = false;
    const batch = queue.splice(0, queue.length);
    for (let index = batch.length - 1; index >= 0; index--) {
      batch[index]?.();
    }
  });
}

import { animate, drag, hover, inView, press, styleEffect } from "motion";
import type { MotionValue } from "motion";
import {
  instantTarget,
  isLabel,
  omitKeys,
  prefersReducedMotion,
  resolveVariant,
  sameMotionValues,
  stripTarget,
  transitionFor,
} from "#/lib/utils/motion/resolve";
import type {
  AnimationControls,
  AnimationRunner,
  DragControls,
  ReducedMotion,
  Target,
  TargetResolver,
  Transition,
  VariantLabels,
  Variants,
  ViewportOptions,
} from "./types";

type Playback = {
  stop: () => void;
  finished?: Promise<unknown>;
  then?: (onFulfilled: () => void) => Promise<unknown>;
};

export interface MotionSnapshot {
  initial: TargetResolver | undefined;
  animate: TargetResolver | AnimationControls | undefined;
  exit: TargetResolver | undefined;
  variants: Variants | undefined;
  transition: Transition | undefined;
  custom: unknown;
  inherit: boolean;
  parentInitial: VariantLabels | false | undefined;
  parentAnimate: VariantLabels | undefined;
  blockInitial: boolean;
  reducedMotion: ReducedMotion | undefined;
  whileHover: TargetResolver | undefined;
  whileTap: TargetResolver | undefined;
  whileFocus: TargetResolver | undefined;
  whileInView: TargetResolver | undefined;
  whileDrag: TargetResolver | undefined;
  drag: boolean | "x" | "y" | undefined;
  dragConstraints: MotionSnapshotConstraints;
  dragElastic: number | boolean | undefined;
  dragMomentum: boolean | undefined;
  dragSnapToOrigin: boolean | "x" | "y" | undefined;
  dragDirectionLock: boolean | undefined;
  dragPropagation: boolean | undefined;
  dragControls: DragControls | undefined;
  viewport: ViewportOptions | undefined;
  onHoverStart: ((event: PointerEvent) => void) | undefined;
  onHoverEnd: ((event: PointerEvent) => void) | undefined;
  onTap: ((event: PointerEvent) => void) | undefined;
  onTapStart: ((event: PointerEvent) => void) | undefined;
  onTapCancel: ((event: PointerEvent) => void) | undefined;
  onDragStart:
    | ((event: PointerEvent, info: { point: { x: number; y: number } }) => void)
    | undefined;
  onDrag: ((event: PointerEvent, info: { point: { x: number; y: number } }) => void) | undefined;
  onDragEnd: ((event: PointerEvent, info: { point: { x: number; y: number } }) => void) | undefined;
  onViewportEnter: (() => void) | undefined;
  onViewportLeave: (() => void) | undefined;
  onUpdate: ((latest: unknown) => void) | undefined;
  styleValues: Record<string, MotionValue>;
}

type MotionSnapshotConstraints =
  | { top?: number; left?: number; right?: number; bottom?: number }
  | Element
  | undefined;

type GestureName = "whileDrag" | "whileTap" | "whileHover" | "whileFocus" | "whileInView";

const gestureOrder: GestureName[] = [
  "whileDrag",
  "whileTap",
  "whileHover",
  "whileFocus",
  "whileInView",
];

const dragStarts = new WeakMap<DragControls, (event: PointerEvent) => void>();

export function bindDragControls(controls: DragControls, start: (event: PointerEvent) => void) {
  dragStarts.set(controls, start);
  return () => {
    if (dragStarts.get(controls) === start) dragStarts.delete(controls);
  };
}

export function startDragControls(controls: DragControls, event: PointerEvent) {
  dragStarts.get(controls)?.(event);
}

function isControls(value: unknown): value is AnimationControls {
  if (!value || typeof value !== "object") return false;
  return "subscribe" in value && "start" in value && "stop" in value;
}

function finished(playback: Playback): Promise<void> {
  return Promise.resolve(playback).then(() => undefined);
}

function reducedNow(config: ReducedMotion | undefined): boolean {
  if (config === "always") return true;
  if (config === "never") return false;
  return prefersReducedMotion();
}

/**
 * One DOM node. Props come in as plain snapshots. Animation, gestures, and
 * motion-value styles go through vanilla `animate`, `hover`, `press`,
 * `inView`, `drag`, and `styleEffect`.
 */
export class MotionState {
  private element: Element | undefined;
  private snap: MotionSnapshot | undefined;
  private current: Playback | undefined;
  private exiting = false;
  private entered = false;
  private lastPlay = "";
  private gestureKey = "";
  private constraints: MotionSnapshotConstraints;
  private styleValues: Record<string, MotionValue> | undefined;
  private styleStop: (() => void) | undefined;
  private gestureStop: Array<() => void> = [];
  private controls: AnimationControls | undefined;
  private unsubscribe: (() => void) | undefined;
  private unbindDrag: (() => void) | undefined;
  private flags: Record<GestureName, boolean> = {
    whileDrag: false,
    whileTap: false,
    whileHover: false,
    whileFocus: false,
    whileInView: false,
  };

  attach(element: Element) {
    this.element = element;
    if (this.snap) this.apply(this.snap);
  }

  prepare(snap: MotionSnapshot) {
    this.snap = snap;
  }

  apply(snap: MotionSnapshot) {
    this.snap = snap;
    if (!this.element) return;
    this.bindStyle(snap.styleValues);
    this.bindGestures(snap);
    this.bindControls(snap);
    if (this.exiting || isControls(snap.animate)) return;
    this.playBase();
  }

  exit(): Promise<void> {
    this.exiting = true;
    const snap = this.snap;
    const element = this.element;
    if (!snap || !element) return Promise.resolve();
    const definition = snap.exit;
    const target = this.targetFrom(definition, snap);
    if (Object.keys(target).length === 0) return Promise.resolve();
    const resolved = resolveVariant(definition, snap.variants, snap.custom);
    return this.start(
      target,
      transitionFor(snap.transition, resolved, snap.onUpdate, reducedNow(snap.reducedMotion)),
    );
  }

  cancelExit() {
    if (!this.exiting) return;
    this.exiting = false;
    this.lastPlay = "";
    this.current?.stop();
    this.playBase();
  }

  destroy() {
    for (const stop of this.gestureStop) stop();
    this.gestureStop = [];
    this.styleStop?.();
    this.unsubscribe?.();
    this.unbindDrag?.();
    if (!this.exiting) this.current?.stop();
    this.element = undefined;
  }

  private bindStyle(values: Record<string, MotionValue>) {
    if (!this.element || sameMotionValues(this.styleValues, values)) return;
    this.styleStop?.();
    this.styleValues = values;
    this.styleStop = Object.keys(values).length > 0 ? styleEffect(this.element, values) : undefined;
  }

  private bindControls(snap: MotionSnapshot) {
    const controls = isControls(snap.animate) ? snap.animate : undefined;
    if (controls === this.controls) return;
    this.unsubscribe?.();
    this.controls = controls;
    if (!controls) {
      this.unsubscribe = undefined;
      return;
    }
    const runner: AnimationRunner = {
      start: (definition, transition) => {
        this.lastPlay = "";
        return this.playDefinition(definition, transition ?? snap.transition, false);
      },
      set: (definition) => {
        this.lastPlay = "";
        return this.playDefinition(definition, { duration: 0 }, true);
      },
      stop: () => this.current?.stop(),
    };
    this.unsubscribe = controls.subscribe(runner);
  }

  private bindGestures(snap: MotionSnapshot) {
    const element = this.element;
    if (!element) return;
    const key = [
      snap.whileHover ? "h" : "",
      snap.onHoverStart ? "hs" : "",
      snap.onHoverEnd ? "he" : "",
      snap.whileTap ? "t" : "",
      snap.onTap ? "ts" : "",
      snap.onTapStart ? "tp" : "",
      snap.whileFocus ? "f" : "",
      snap.whileInView ? "v" : "",
      snap.onViewportEnter ? "ve" : "",
      snap.onViewportLeave ? "vl" : "",
      snap.viewport?.once ? "o" : "",
      snap.viewport?.margin ?? "",
      String(snap.viewport?.amount ?? ""),
      String(snap.drag ?? ""),
      String(snap.dragMomentum ?? ""),
      String(snap.dragSnapToOrigin ?? ""),
      String(snap.dragDirectionLock ?? ""),
      String(snap.dragPropagation ?? ""),
      String(snap.dragElastic ?? ""),
    ].join("|");
    if (
      key === this.gestureKey &&
      snap.dragConstraints === this.constraints &&
      snap.dragControls === this.boundDrag
    ) {
      return;
    }
    this.gestureKey = key;
    this.constraints = snap.dragConstraints;
    this.boundDrag = snap.dragControls;
    for (const stop of this.gestureStop) stop();
    this.gestureStop = [];
    this.unbindDrag?.();
    this.unbindDrag = undefined;

    if (snap.whileHover || snap.onHoverStart || snap.onHoverEnd) {
      this.gestureStop.push(
        hover(element, (_node, event) => {
          this.flags.whileHover = true;
          this.snap?.onHoverStart?.(event);
          this.lastPlay = "";
          this.playBase();
          return (end) => {
            this.flags.whileHover = false;
            this.snap?.onHoverEnd?.(end);
            this.lastPlay = "";
            this.playBase();
          };
        }),
      );
    }

    if (snap.whileTap || snap.onTap || snap.onTapStart || snap.onTapCancel) {
      this.gestureStop.push(
        press(element, (_node, event) => {
          this.flags.whileTap = true;
          this.snap?.onTapStart?.(event);
          this.lastPlay = "";
          this.playBase();
          return (end, info) => {
            this.flags.whileTap = false;
            if (info.success) this.snap?.onTap?.(end);
            else this.snap?.onTapCancel?.(end);
            this.lastPlay = "";
            this.playBase();
          };
        }),
      );
    }

    if (snap.whileFocus) {
      const onFocus = () => {
        this.flags.whileFocus = true;
        this.lastPlay = "";
        this.playBase();
      };
      const onBlur = () => {
        this.flags.whileFocus = false;
        this.lastPlay = "";
        this.playBase();
      };
      element.addEventListener("focus", onFocus);
      element.addEventListener("blur", onBlur);
      this.gestureStop.push(() => {
        element.removeEventListener("focus", onFocus);
        element.removeEventListener("blur", onBlur);
      });
    }

    if (snap.whileInView || snap.onViewportEnter || snap.onViewportLeave) {
      this.gestureStop.push(
        inView(
          element,
          () => {
            this.flags.whileInView = true;
            this.snap?.onViewportEnter?.();
            this.lastPlay = "";
            this.playBase();
            if (snap.viewport?.once) return;
            return () => {
              this.flags.whileInView = false;
              this.snap?.onViewportLeave?.();
              this.lastPlay = "";
              this.playBase();
            };
          },
          {
            amount: snap.viewport?.amount,
            margin: snap.viewport?.margin,
          },
        ),
      );
    }

    if (snap.drag) {
      const axis = snap.drag === true ? undefined : snap.drag;
      this.gestureStop.push(
        drag(element, {
          axis,
          constraints: snap.dragConstraints,
          elastic: snap.dragElastic,
          momentum: snap.dragMomentum,
          snapToOrigin: snap.dragSnapToOrigin,
          directionLock: snap.dragDirectionLock,
          propagation: snap.dragPropagation,
          onStart: (event, info) => {
            this.flags.whileDrag = true;
            if (event instanceof PointerEvent)
              this.snap?.onDragStart?.(event, { point: info.point });
            this.lastPlay = "";
            this.playBase();
          },
          onMove: (event, info) => {
            if (event instanceof PointerEvent) this.snap?.onDrag?.(event, { point: info.point });
          },
          onEnd: (event, info) => {
            this.flags.whileDrag = false;
            if (event instanceof PointerEvent) this.snap?.onDragEnd?.(event, { point: info.point });
            this.lastPlay = "";
            this.playBase();
          },
        }),
      );
      if (snap.dragControls) {
        this.unbindDrag = bindDragControls(snap.dragControls, (event) => {
          element.dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              clientX: event.clientX,
              clientY: event.clientY,
              pointerId: event.pointerId,
              pointerType: event.pointerType,
            }),
          );
        });
      }
    }
  }

  private boundDrag: DragControls | undefined;

  private playBase() {
    const snap = this.snap;
    if (!snap || !this.element || this.exiting) return;
    const active = this.activeDefinition(snap);
    if (active !== undefined) {
      void this.playDefinition(active, snap.transition, false);
      return;
    }
    const base = this.baseDefinition(snap);
    if (!this.entered) {
      this.entered = true;
      const jump = snap.blockInitial || snap.initial === false;
      if (jump) {
        void this.playDefinition(base, snap.transition, true);
        return;
      }
      const initial =
        snap.initial !== undefined
          ? snap.initial
          : snap.inherit === false
            ? undefined
            : snap.parentInitial;
      if (initial && !isControls(initial)) {
        const pose = this.targetFrom(initial, snap);
        if (Object.keys(pose).length > 0) {
          void this.start(instantTarget(pose), { duration: 0 }).then(() => {
            if (!this.element || this.exiting) return;
            void this.playDefinition(base, snap.transition, false);
          });
          return;
        }
      }
    }
    void this.playDefinition(base, snap.transition, false);
  }

  private baseDefinition(snap: MotionSnapshot): TargetResolver | undefined {
    if (snap.animate !== undefined && !isControls(snap.animate)) return snap.animate;
    if (snap.inherit === false) return undefined;
    return snap.parentAnimate;
  }

  private activeDefinition(snap: MotionSnapshot): TargetResolver | undefined {
    for (const name of gestureOrder) {
      if (!this.flags[name]) continue;
      const definition = snap[name];
      if (definition !== undefined) return definition;
    }
    return undefined;
  }

  private playDefinition(
    definition: TargetResolver | undefined,
    transition: Transition | undefined,
    instant: boolean,
  ): Promise<void> {
    const snap = this.snap;
    if (!snap) return Promise.resolve();
    if (!instant && isLabel(definition) && Array.isArray(definition) && definition.length > 1) {
      return this.playLabels(definition, transition);
    }
    const resolved = resolveVariant(definition, snap.variants, snap.custom);
    const target = this.targetFrom(definition, snap);
    if (Object.keys(target).length === 0) return Promise.resolve();
    const options = transitionFor(
      transition,
      resolved,
      snap.onUpdate,
      reducedNow(snap.reducedMotion) || instant,
    );
    if (instant) {
      const pose = instantTarget(target);
      const key = JSON.stringify(pose);
      if (key === this.lastPlay) return Promise.resolve();
      this.lastPlay = key;
      return this.start(pose, { duration: 0 });
    }
    const key = JSON.stringify({ target, options });
    if (key === this.lastPlay) return Promise.resolve();
    this.lastPlay = key;
    return this.start(target, options);
  }

  private playLabels(labels: string[], transition: Transition | undefined): Promise<void> {
    const element = this.element;
    let chain = Promise.resolve();
    for (const label of labels) {
      chain = chain.then(() => {
        if (this.element !== element || this.exiting) return undefined;
        this.lastPlay = "";
        return this.playDefinition(label, transition, false);
      });
    }
    return chain;
  }

  private targetFrom(definition: TargetResolver | undefined, snap: MotionSnapshot): Target {
    const resolved = resolveVariant(definition, snap.variants, snap.custom);
    return omitKeys(stripTarget(resolved), Object.keys(snap.styleValues));
  }

  private start(target: Target, options: Transition): Promise<void> {
    const element = this.element;
    if (!element || Object.keys(target).length === 0) return Promise.resolve();
    const playback = animate(element, target, options);
    this.current = playback;
    return finished(playback);
  }
}

import type { JSX } from "solid-js";
import type { Target } from "#/lib/motion/types";

type TransformKey =
  | "x"
  | "y"
  | "z"
  | "scale"
  | "scaleX"
  | "scaleY"
  | "rotate"
  | "rotateX"
  | "rotateY"
  | "rotateZ"
  | "skewX"
  | "skewY";

const transformOrder: TransformKey[] = [
  "x",
  "y",
  "z",
  "scale",
  "scaleX",
  "scaleY",
  "rotate",
  "rotateX",
  "rotateY",
  "rotateZ",
  "skewX",
  "skewY",
];

function px(value: string | number): string {
  return typeof value === "number" ? `${value}px` : value;
}

function deg(value: string | number): string {
  return typeof value === "number" ? `${value}deg` : value;
}

function scalar(value: string | number): string {
  return String(value);
}

const transformFns: Record<TransformKey, (value: string | number) => string> = {
  x: (value) => `translateX(${px(value)})`,
  y: (value) => `translateY(${px(value)})`,
  z: (value) => `translateZ(${px(value)})`,
  scale: (value) => `scale(${scalar(value)})`,
  scaleX: (value) => `scaleX(${scalar(value)})`,
  scaleY: (value) => `scaleY(${scalar(value)})`,
  rotate: (value) => `rotate(${deg(value)})`,
  rotateX: (value) => `rotateX(${deg(value)})`,
  rotateY: (value) => `rotateY(${deg(value)})`,
  rotateZ: (value) => `rotateZ(${deg(value)})`,
  skewX: (value) => `skewX(${deg(value)})`,
  skewY: (value) => `skewY(${deg(value)})`,
};

export function isTransformKey(key: string): key is TransformKey {
  return key in transformFns;
}

/** Static pose for the first paint. Motion's `animate()` owns later frames. */
export function targetToStyle(target: Target): JSX.CSSProperties {
  const style: Record<string, string | number> = {};
  const transform: string[] = [];
  for (const key of transformOrder) {
    const value = target[key];
    if (typeof value === "number" || typeof value === "string") {
      transform.push(transformFns[key](value));
    }
  }
  for (const key in target) {
    if (isTransformKey(key)) continue;
    const value = target[key];
    if (typeof value === "number" || typeof value === "string") style[key] = value;
  }
  if (transform.length > 0) style.transform = transform.join(" ");
  return style;
}

export function pinPopLayout(
  element: HTMLElement,
  anchorX: "left" | "right",
  anchorY: "top" | "bottom",
): () => void {
  const parent =
    element.offsetParent instanceof HTMLElement ? element.offsetParent : element.parentElement;
  const top = element.offsetTop;
  const left = element.offsetLeft;
  const width = element.offsetWidth;
  const height = element.offsetHeight;
  const previous = {
    position: element.style.position,
    width: element.style.width,
    height: element.style.height,
    top: element.style.top,
    left: element.style.left,
    right: element.style.right,
    bottom: element.style.bottom,
  };
  element.style.position = "absolute";
  element.style.width = `${width}px`;
  element.style.height = `${height}px`;
  if (anchorX === "left") element.style.left = `${left}px`;
  else element.style.right = `${(parent?.clientWidth ?? width) - width - left}px`;
  if (anchorY === "top") element.style.top = `${top}px`;
  else element.style.bottom = `${(parent?.clientHeight ?? height) - height - top}px`;
  return () => {
    element.style.position = previous.position;
    element.style.width = previous.width;
    element.style.height = previous.height;
    element.style.top = previous.top;
    element.style.left = previous.left;
    element.style.right = previous.right;
    element.style.bottom = previous.bottom;
  };
}

import type { AnimationOptions, MotionValue } from "motion";
import type { JSX } from "solid-js";

export type Transition = AnimationOptions;

/** A variant label, or several played in order. */
export type VariantLabels = string | string[];

export type Animatable = string | number | Array<string | number>;

export type Target = Record<string, Animatable | undefined>;

export type TargetAndTransition = Target & {
  transition?: Transition;
};

export type Variant = TargetAndTransition | ((custom: unknown) => TargetAndTransition);

export type TargetResolver = boolean | TargetAndTransition | VariantLabels | Variant;

export type Variants = Record<string, Variant>;

export type ReducedMotion = "user" | "always" | "never";

export type DragAxis = boolean | "x" | "y";

export interface DragConstraints {
  top?: number;
  left?: number;
  right?: number;
  bottom?: number;
}

export interface ViewportOptions {
  once?: boolean;
  margin?: `${number}px` | `${number}%` | `${number}px ${number}px` | `${number}% ${number}%`;
  amount?: "some" | "all" | number;
}

export type GestureInfo = {
  point: { x: number; y: number };
};

export type MotionStyleKey =
  | "x"
  | "y"
  | "z"
  | "scale"
  | "scaleX"
  | "scaleY"
  | "rotate"
  | "rotateX"
  | "rotateY"
  | "rotateZ"
  | "skewX"
  | "skewY";

export type MotionStyleValue = string | number | MotionValue<number> | MotionValue<string>;

export type MotionStyle = Omit<JSX.CSSProperties, MotionStyleKey> &
  Partial<Record<MotionStyleKey, MotionStyleValue>>;

export interface AnimationControls {
  start: (definition: TargetResolver, transition?: Transition) => Promise<void>;
  set: (definition: TargetResolver) => void;
  stop: () => void;
